#!/bin/bash
# PlotNua · @@TITLE@@ (prepared @@DATE@@).
# Generated by atlas-tools/release/make-release-scripts.py from atlas-tools/release/deploy-template.sh.
# Run ONLY after Colin gives explicit release approval.
#   bash @@SCRIPT@@ --stage     run every check, push ONLY the release branch, wait for the Image Rights Gate
#   bash @@SCRIPT@@ --status    read the Image Rights Gate result for this exact release commit
#   bash @@SCRIPT@@ --release   after a green gate on this exact commit, and your typed confirmation,
#                               fast-forward main to the release commit
# The gate starts by itself when the release branch is pushed. This script never starts it, and it
# accepts only a green run on THIS commit on THIS branch: a green run on any other commit never counts.
# It never force-pushes, never deploys without your typed confirmation, and pushes nothing unless every check passes.
set -u
HERE="$(cd "$(dirname "$0")" && pwd)"
REPO="${PLOTNUA_REPO:-$HOME/Documents/PlotNua/04 Deploy/plotnua-grower-release}"
BUNDLE="$HERE/@@BUNDLE@@"
BUNDLE_SHA=@@BUNDLE_SHA@@
BR=@@BRANCH@@
MAIN=@@MAIN@@          # production when this release was prepared
REL=@@REL@@
TREE=@@TREE@@
NCOMMITS=@@N@@
WANT="@@WANT@@"
die(){ echo "REFUSED: $*  -- nothing pushed"; exit 1; }
ok(){ echo "OK   $*"; }
MODE="${1:-}"; case "$MODE" in --stage|--status|--release) ;; *) die "say --stage, --status or --release";; esac
cd "$REPO" || die "no repository at $REPO"
git fetch -q origin || die "cannot fetch origin"
[ "$(git rev-parse origin/main)" = "$MAIN" ] || die "origin/main is $(git rev-parse --short origin/main), not ${MAIN:0:7}: main has moved; stop and integrate first"
ok "origin/main is ${MAIN:0:7} (production)"
[ "$(shasum -a 256 "$BUNDLE" | cut -c1-64)" = "$BUNDLE_SHA" ] || die "bundle SHA-256 differs from the one tested"
git bundle verify "$BUNDLE" >/dev/null 2>&1 || die "bundle does not verify against this repository"
git fetch -q "$BUNDLE" "$BR:refs/remotes/bundle/release" || die "cannot read the bundle"
[ "$(git rev-parse bundle/release)" = "$REL" ] || die "bundle branch is not ${REL:0:7}"
[ "$(git rev-parse "$REL^{tree}")" = "$TREE" ] || die "release tree differs"
git merge-base --is-ancestor "$MAIN" "$REL" || die "not a fast-forward of main"
[ "$(git rev-list --count "$MAIN..$REL")" = "$NCOMMITS" ] || die "expected exactly $NCOMMITS commit(s) on top of main"
ok "release commit ${REL:0:7}, tree ${TREE:0:8}, $NCOMMITS clean fast-forward commit(s)"
CH="$(git diff --name-only "$MAIN" "$REL" | LC_ALL=C sort | tr '\n' ' ')"
[ "$CH" = "$WANT" ] || die "changed files are not exactly the approved set: $CH"
ok "exactly the approved files changed"
git log --format=%B "$MAIN..$REL" | grep -qiE '\[(skip ci|ci skip|no ci|skip actions|actions skip)\]' && die "a commit message would stop the gate from running"
git show "$REL:.github/workflows/image-rights-gate.yml" | grep -q "branches: \[main, 'release/\*\*'\]" || die "the release's gate does not run on release/* pushes"
git cat-file -e "$REL:atlas-tools/release/gate-result.py" 2>/dev/null || die "the release has no gate reader"
ok "the gate runs by itself on $BR"
W="$(mktemp -d)"; git worktree add -q --detach "$W" "$REL" || die "cannot check out the release"
trap 'git -C "$REPO" worktree remove --force "$W" >/dev/null 2>&1' EXIT
gate(){ python3 "$W/atlas-tools/release/gate-result.py" --sha "$REL" --branch "$BR" "$@"; }
if [ "$MODE" = "--status" ]; then gate; exit $?; fi
( cd "$W" &&
@@CHECKS@@
  true ) || die "a check failed in the release tree"
if [ "$MODE" = "--stage" ]; then
  X="$(git ls-remote origin "refs/heads/$BR" | cut -f1)"
  [ -z "$X" ] || [ "$X" = "$REL" ] || die "origin already has $BR at ${X:0:7}: it is not ours, stop"
  if [ "$X" = "$REL" ]; then ok "$BR is already on GitHub at ${REL:0:7} (not pushed again)"
  else git push origin "$REL:refs/heads/$BR" || die "push of the release branch failed"; ok "pushed $BR only (main untouched)"; fi
  echo "WAITING for the Image Rights Gate on ${REL:0:7} (it starts by itself; up to 20 minutes) ..."
  gate --wait "${PN_GATE_WAIT:-1200}"; G=$?
  case $G in
    0) echo "STAGED $BR at ${REL:0:7} · gate PASSED on this exact commit. Production is unchanged."
       echo "WHEN YOU APPROVE: bash $(basename "$0") --release" ;;
    2) die "the gate FAILED on ${REL:0:7}: do not release" ;;
    *) echo "STAGED $BR at ${REL:0:7} · gate result not final yet: check later with  bash $(basename "$0") --status"; exit 3 ;;
  esac
  exit 0
fi
# --release
[ "$(git ls-remote origin "refs/heads/$BR" | cut -f1)" = "$REL" ] || die "stage first: origin/$BR is not ${REL:0:7}"
gate || die "the Image Rights Gate has not passed on exactly ${REL:0:7} (see above)"
[ -t 0 ] && [ -r /dev/tty ] || die "the release needs you at the keyboard to confirm"
echo
echo "This updates PRODUCTION: main ${MAIN:0:7} -> ${REL:0:7} (@@TITLE@@)."
printf "Type  RELEASE %s  to confirm: " "${REL:0:7}"
read -r ANSWER </dev/tty
[ "$ANSWER" = "RELEASE ${REL:0:7}" ] || die "not confirmed"
git fetch -q origin && [ "$(git rev-parse origin/main)" = "$MAIN" ] || die "main moved during the checks"
[ "$(git ls-remote origin "refs/heads/$BR" | cut -f1)" = "$REL" ] || die "the release branch moved"
git push origin "$REL:refs/heads/main" || die "push to main refused (not a fast-forward?)"
echo "DEPLOYED ${REL:0:7}  main ${MAIN:0:7} -> ${REL:0:7} (fast-forward, tree ${TREE:0:8})"
echo "NEXT: Claude verifies production."
